1	package org.springframework.samples.petclinic.mapper;
2	
3	import org.jspecify.annotations.NonNull;
4	import org.mapstruct.Mapper;
5	import org.mapstruct.Mapping;
6	import org.mapstruct.Named;
7	import org.springframework.data.domain.Page;
8	import org.springframework.samples.petclinic.model.Owner;
9	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
10	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
11	import org.springframework.samples.petclinic.rest.dto.OwnerPageDto;
12	import org.springframework.samples.petclinic.rest.validation.E164Telephone;
13	import org.springframework.samples.petclinic.util.AddressNormalizer;
14	import org.springframework.samples.petclinic.util.Regions;
15	
16	import java.time.LocalDate;
17	import java.util.Collection;
18	import java.util.List;
19	
20	/**
21	 * Maps Owner & OwnerDto using Mapstruct
22	 */
23	@Mapper(uses = PetMapper.class)
24	public interface OwnerMapper {
25	
26	    @Mapping(target = "selfLink", expression = "java(formatSelfLink(owner))")
27	    @Mapping(target = "displayName", expression = "java(formatDisplayName(owner))")
28	    @Mapping(target = "salutation", expression = "java(formatSalutation(owner))")
29	    @Mapping(target = "initials", expression = "java(formatInitials(owner))")
30	    @Mapping(target = "telephoneDisplay", expression = "java(formatTelephoneDisplay(owner))")
31	    @Mapping(target = "checkDigit", expression = "java(formatCheckDigit(owner))")
32	    @Mapping(target = "membershipNumber", expression = "java(formatMembershipNumber(owner))")
33	    @Mapping(target = "fiscalYear", expression = "java(formatFiscalYear(owner))")
34	    @Mapping(target = "membershipPoints", expression = "java(formatMembershipPoints(owner))")
35	    @Mapping(target = "membershipLevel", expression = "java(formatMembershipLevel(owner))")
36	    @Mapping(target = "locality", expression = "java(formatLocality(owner))")
37	    @Mapping(target = "timezone", expression = "java(formatTimezone(owner))")
38	    @Mapping(target = "bulkSignupWarning", expression = "java(formatBulkSignupWarning(owner))")
39	    @Mapping(target = "capacityWarning", expression = "java(formatCapacityWarning(owner))")
40	    @Mapping(target = "possibleDuplicate", expression = "java(formatPossibleDuplicate(owner))")
41	    @Mapping(target = "contactPreference", expression = "java(formatContactPreference(owner))")
42	    @Mapping(target = "ageBand", expression = "java(formatAgeBand(owner))")
43	    @Mapping(target = "ownerSegment", expression = "java(formatOwnerSegment(owner))")
44	    OwnerDto toOwnerDto(Owner owner);
45	
46	    /**
47	     * Derive an owner's marketing segment, formatted {@code "<TIER>_<AREA>"}. The tier is
48	     * {@code "PREMIUM"} when the owner's {@code membershipLevel} (see
49	     * {@link #formatMembershipLevel(Owner)}) is {@code 3} or more, otherwise {@code "STANDARD"}.
50	     * The area is {@code "METRO"} when the owner's locality (see {@link #formatLocality(Owner)}) is
51	     * a known region (NSW, VIC or QLD), otherwise {@code "REGIONAL"}. Returns one of
52	     * {@code "PREMIUM_METRO"}, {@code "PREMIUM_REGIONAL"}, {@code "STANDARD_METRO"} or
53	     * {@code "STANDARD_REGIONAL"}; {@code null} only when the owner is {@code null}.
54	     */
55	    default String formatOwnerSegment(Owner owner) {
56	        if (owner == null) {
57	            return null;
58	        }
59	        Integer level = formatMembershipLevel(owner);
60	        String tier = level != null && level >= 3 ? "PREMIUM" : "STANDARD";
61	        String area = Regions.isKnownRegion(formatLocality(owner)) ? "METRO" : "REGIONAL";
62	        return tier + "_" + area;
63	    }
64	
65	    /**
66	     * Resolve an owner's possible-duplicate flag, coalescing a {@code null} stored value
67	     * (e.g. for owners created before the flag existed) to {@code false} so the response
68	     * always carries an explicit boolean.
69	     */
70	    default Boolean formatPossibleDuplicate(Owner owner) {
71	        if (owner == null) {
72	            return null;
73	        }
74	        return Boolean.TRUE.equals(owner.getPossibleDuplicate());
75	    }
76	
77	    /**
78	     * Derive an owner's age band from its {@code birthDate}, measured as the owner's age in whole
79	     * years on its {@code registrationDate}: {@code "MINOR"} when under 18, {@code "ADULT"} from 18
80	     * through 64, and {@code "SENIOR"} at 65 and over. Returns {@code null} when the owner, its
81	     * birth date or its registration date is absent, since the band cannot be derived without both
82	     * dates.
83	     */
84	    default String formatAgeBand(Owner owner) {
85	        if (owner == null || owner.getBirthDate() == null || owner.getRegistrationDate() == null) {
86	            return null;
87	        }
88	        int age = java.time.Period.between(owner.getBirthDate(), owner.getRegistrationDate()).getYears();
89	        if (age < 18) {
90	            return "MINOR";
91	        }
92	        if (age < 65) {
93	            return "ADULT";
94	        }
95	        return "SENIOR";
96	    }
97	
98	    /**
99	     * Derive an owner's preferred contact channel from its stored contact details:
100	     * {@code "EMAIL"} when a (non-blank) email address is present, otherwise {@code "PHONE"}.
101	     */
102	    default String formatContactPreference(Owner owner) {
103	        if (owner == null) {
104	            return null;
105	        }
106	        boolean hasEmail = owner.getEmail() != null && !owner.getEmail().isEmpty();
107	        return hasEmail ? "EMAIL" : "PHONE";
108	    }
109	
110	    /**
111	     * Resolve an owner's bulk-signup warning flag, coalescing a {@code null} stored value
112	     * (e.g. for owners created before the flag existed) to {@code false} so the response
113	     * always carries an explicit boolean.
114	     */
115	    default Boolean formatBulkSignupWarning(Owner owner) {
116	        if (owner == null) {
117	            return null;
118	        }
119	        return Boolean.TRUE.equals(owner.getBulkSignupWarning());
120	    }
121	
122	    /**
123	     * Resolve an owner's capacity-warning flag, coalescing a {@code null} stored value
124	     * (e.g. for owners created before the flag existed) to {@code false} so the response
125	     * always carries an explicit boolean.
126	     */
127	    default Boolean formatCapacityWarning(Owner owner) {
128	        if (owner == null) {
129	            return null;
130	        }
131	        return Boolean.TRUE.equals(owner.getCapacityWarning());
132	    }
133	
134	    /**
135	     * Derive an owner's locality from its region-and-hash identity: the {@code <REGION>} segment
136	     * of the {@code customerCode} (the part before the first hyphen), which is the region code
137	     * derived from the owner's postcode. For an owner that has not yet been assigned a customer
138	     * code, the region is derived directly from the postcode (see {@link Regions#forPostcode}),
139	     * yielding the same value the code would carry. Returns {@code null} only when the owner
140	     * itself is {@code null}.
141	     */
142	    default String formatLocality(Owner owner) {
143	        if (owner == null) {
144	            return null;
145	        }
146	        String code = owner.getCustomerCode();
147	        if (code != null) {
148	            int hyphen = code.indexOf('-');
149	            return hyphen >= 0 ? code.substring(0, hyphen) : code;
150	        }
151	        return Regions.forPostcode(owner.getPostcode());
152	    }
153	
154	    /**
155	     * Derive an owner's timezone as the IANA name mapped from its locality/region via a fixed
156	     * region-to-timezone table (see {@link Regions#timezoneForRegion}): NSW -> Australia/Sydney,
157	     * VIC -> Australia/Melbourne, QLD -> Australia/Brisbane. Returns {@code null} when the owner
158	     * is {@code null} or its region is not in the table.
159	     */
160	    default String formatTimezone(Owner owner) {
161	        if (owner == null) {
162	            return null;
163	        }
164	        return Regions.timezoneForRegion(formatLocality(owner));
165	    }
166	
167	    /**
168	     * Compute an owner's membership points. Points start at {@code 0} and gain: {@code 2} when an
169	     * email address is present; {@code 1} when the owner has no namesakes (its
170	     * {@code namesakeCount} is {@code 0}); {@code 2} for a household of three or more members (the
171	     * owner plus its pets); and {@code 3} when the owner's tenure (the number of fiscal years
172	     * elapsed since its {@code registrationDate}'s fiscal year) exceeds {@code 1}. A null or absent
173	     * namesake count is treated as not being zero, so it contributes nothing.
174	     */
175	    default Integer formatMembershipPoints(Owner owner) {
176	        if (owner == null) {
177	            return null;
178	        }
179	        int points = 0;
180	        boolean hasEmail = owner.getEmail() != null && !owner.getEmail().isEmpty();
181	        if (hasEmail) {
182	            points += 2;
183	        }
184	        boolean uniqueName = owner.getNamesakeCount() != null && owner.getNamesakeCount() == 0;
185	        if (uniqueName) {
186	            points += 1;
187	        }
188	        int householdSize = 1 + (owner.getPets() == null ? 0 : owner.getPets().size());
189	        if (householdSize >= 3) {
190	            points += 2;
191	        }
192	        LocalDate registrationDate = owner.getRegistrationDate();
193	        if (registrationDate != null
194	            && fiscalYearEndYear(LocalDate.now()) - fiscalYearEndYear(registrationDate) > 1) {
195	            points += 3;
196	        }
197	        return points;
198	    }
199	
200	    /**
201	     * Determine an owner's membership level, a number from {@code 1} to {@code 4} derived from its
202	     * membership points (see {@link #formatMembershipPoints(Owner)}): level {@code 1} for
203	     * {@code 0}-{@code 1} points, {@code 2} for {@code 2}-{@code 3}, {@code 3} for {@code 4}-{@code 5}
204	     * and {@code 4} for {@code 6} or more.
205	     *
206	     * <p>The level is then capped by the owner's {@code membershipLevelCap} when one is present (see
207	     * {@link Owner#getMembershipLevelCap()}): a new owner's level may not exceed one above the
208	     * current maximum level among its existing household members, so the returned value is the
209	     * smaller of the points-derived level and the cap. A {@code null} cap means no household ceiling
210	     * applies and the points-derived level is returned unchanged.
211	     */
212	    default Integer formatMembershipLevel(Owner owner) {
213	        if (owner == null) {
214	            return null;
215	        }
216	        int points = formatMembershipPoints(owner);
217	        int level;
218	        if (points <= 1) {
219	            level = 1;
220	        }
221	        else if (points <= 3) {
222	            level = 2;
223	        }
224	        else if (points <= 5) {
225	            level = 3;
226	        }
227	        else {
228	            level = 4;
229	        }
230	        Integer cap = owner.getMembershipLevelCap();
231	        if (cap != null && cap < level) {
232	            return cap;
233	        }
234	        return level;
235	    }
236	
237	    /**
238	     * Compute an owner's check digit: a single Luhn check digit (0-9) over the digits
239	     * contained in the owner's {@code customerCode}. Non-digit characters (the region segment
240	     * and any hex letters of the hash) are ignored. Returns {@code null} when the owner or its
241	     * customer code is absent, since the digit cannot be derived without the code.
242	     */
243	    default Integer formatCheckDigit(Owner owner) {
244	        if (owner == null || owner.getCustomerCode() == null) {
245	            return null;
246	        }
247	        String code = owner.getCustomerCode();
248	        int sum = 0;
249	        boolean dbl = true;
250	        for (int i = code.length() - 1; i >= 0; i--) {
251	            char c = code.charAt(i);
252	            if (c < '0' || c > '9') {
253	                continue;
254	            }
255	            int d = c - '0';
256	            if (dbl) {
257	                d *= 2;
258	                if (d > 9) {
259	                    d -= 9;
260	                }
261	            }
262	            sum += d;
263	            dbl = !dbl;
264	        }
265	        return (10 - (sum % 10)) % 10;
266	    }
267	
268	    /**
269	     * Format an owner's membership number as {@code "<customerCode>-M<YY>"}, where {@code YY}
270	     * is the last two digits of the owner's fiscal year (see {@link #formatFiscalYear(Owner)}),
271	     * the fiscal year of the business-day-adjusted registration date (e.g.
272	     * {@code "NSW-3F5A9C2E-M26"}). Returns {@code null} when either the customer code or
273	     * registration date is absent, since the number cannot be derived without both.
274	     */
275	    default String formatMembershipNumber(Owner owner) {
276	        if (owner == null || owner.getCustomerCode() == null || owner.getRegistrationDate() == null) {
277	            return null;
278	        }
279	        return String.format("%s-M%02d", owner.getCustomerCode(),
280	            fiscalYearEndYear(owner.getRegistrationDate()) % 100);
281	    }
282	
283	    /**
284	     * Format an owner's fiscal year as {@code "FY<YY>"}, where {@code YY} is the last two digits
285	     * of the fiscal year its (business-day-adjusted) {@code registrationDate} falls in (e.g.
286	     * {@code "FY26"}). The fiscal year starts on 1 July and is named by the calendar year in
287	     * which it ends, so a registration date of {@code 2026-07-01} is {@code "FY27"} while
288	     * {@code 2026-06-30} is {@code "FY26"}. Returns {@code null} when the owner or its
289	     * registration date is absent.
290	     */
291	    default String formatFiscalYear(Owner owner) {
292	        if (owner == null || owner.getRegistrationDate() == null) {
293	            return null;
294	        }
295	        return String.format("FY%02d", fiscalYearEndYear(owner.getRegistrationDate()) % 100);
296	    }
297	
298	    /**
299	     * The calendar year in which {@code date}'s fiscal year ends, used as the fiscal year's name.
300	     * The fiscal year starts on 1 July, so a date in July through December belongs to the fiscal
301	     * year ending the following calendar year, while January through June belongs to the one
302	     * ending in the current calendar year.
303	     */
304	    default int fiscalYearEndYear(LocalDate date) {
305	        return date.getMonthValue() >= java.time.Month.JULY.getValue() ? date.getYear() + 1 : date.getYear();
306	    }
307	
308	    /**
309	     * Format an owner's stored E.164 telephone for humans as the country code, a space, then the
310	     * national digits grouped in threes, e.g. {@code "+61412345678"} becomes
311	     * {@code "+61 412 345 678"} (see {@link E164Telephone#toDisplay}). The raw {@code telephone}
312	     * is left in E.164 form. Returns {@code null} when the owner or its telephone is absent.
313	     */
314	    default String formatTelephoneDisplay(Owner owner) {
315	        if (owner == null) {
316	            return null;
317	        }
318	        return E164Telephone.toDisplay(owner.getTelephone());
319	    }
320	
321	    /**
322	     * Compose an owner's salutation as its {@code title} followed by a single space and the
323	     * last name (e.g. {@code "DR Franklin"}). When no title was supplied (null or blank) the
324	     * salutation is just the last name. Returns {@code null} when the owner is {@code null}.
325	     */
326	    default String formatSalutation(Owner owner) {
327	        if (owner == null) {
328	            return null;
329	        }
330	        String title = owner.getTitle();
331	        if (title == null || title.trim().isEmpty()) {
332	            return owner.getLastName();
333	        }
334	        return title + " " + owner.getLastName();
335	    }
336	
337	    /**
338	     * Build a link to an owner's own resource, formed as {@code "/api/owners/"} followed by the
339	     * owner's id. Returns {@code null} when the owner or its id is absent, since the link cannot
340	     * be formed without an id.
341	     */
342	    default String formatSelfLink(Owner owner) {
343	        if (owner == null || owner.getId() == null) {
344	            return null;
345	        }
346	        return "/api/owners/" + owner.getId();
347	    }
348	
349	    /**
350	     * Format an owner's name as {@code "LastName, FirstName"} from the stored names.
351	     */
352	    default String formatDisplayName(Owner owner) {
353	        if (owner == null) {
354	            return null;
355	        }
356	        return owner.getLastName() + ", " + owner.getFirstName();
357	    }
358	
359	    /**
360	     * Format an owner's initials as the upper-cased first letters of the first and last
361	     * names, dot-separated with a trailing dot, e.g. {@code "J.S."}.
362	     */
363	    default String formatInitials(Owner owner) {
364	        if (owner == null) {
365	            return null;
366	        }
367	        return Character.toUpperCase(owner.getFirstName().charAt(0)) + "."
368	            + Character.toUpperCase(owner.getLastName().charAt(0)) + ".";
369	    }
370	
371	    Owner toOwner(OwnerDto ownerDto);
372	
373	    @Mapping(target = "id", ignore = true)
374	    @Mapping(target = "pets", ignore = true)
375	    @Mapping(target = "namesakeCount", ignore = true)
376	    @Mapping(target = "bulkSignupWarning", ignore = true)
377	    @Mapping(target = "capacityWarning", ignore = true)
378	    @Mapping(target = "possibleDuplicate", ignore = true)
379	    @Mapping(target = "possibleDuplicateOf", ignore = true)
380	    @Mapping(target = "membershipLevelCap", ignore = true)
381	    @Mapping(target = "address", expression = "java(composeAddress(ownerDto))")
382	    @Mapping(target = "addressLine1", source = "addressLine1", qualifiedByName = "normalizeAddress")
383	    @Mapping(target = "addressLine2", source = "addressLine2", qualifiedByName = "normalizeAddress")
384	    @Mapping(target = "telephone", source = "telephone", qualifiedByName = "normalizeTelephone")
385	    @Mapping(target = "email", source = "email", qualifiedByName = "normalizeEmail")
386	    Owner toOwner(OwnerFieldsDto ownerDto);
387	
388	    /**
389	     * Normalize a postal address for storage into its canonical form (see
390	     * {@link AddressNormalizer}), so it is persisted and returned the same way regardless of
391	     * the formatting supplied by the caller. {@code @Named} keeps this out of MapStruct's
392	     * automatic method selection, so it only runs where a mapping explicitly references it via
393	     * {@code qualifiedByName}.
394	     */
395	    @Named("normalizeAddress")
396	    default String normalizeAddress(String address) {
397	        return AddressNormalizer.normalize(address);
398	    }
399	
400	    /**
401	     * Compose the single stored/returned {@code address} from whichever address fields the request
402	     * supplies, preferring the structured form. When a non-blank {@code addressLine1} is present the
403	     * composed value is the normalized {@code addressLine1} (see {@link AddressNormalizer}), with a
404	     * single space and the normalized {@code addressLine2} appended when {@code addressLine2} is
405	     * present; otherwise it falls back to the normalized flat {@code address}. This keeps everything
406	     * that reads the stored address consistent regardless of which form the caller used.
407	     */
408	    default String composeAddress(OwnerFieldsDto ownerDto) {
409	        if (ownerDto == null) {
410	            return null;
411	        }
412	        String line1 = ownerDto.getAddressLine1();
413	        if (line1 != null && !line1.trim().isEmpty()) {
414	            String composed = AddressNormalizer.normalize(line1);
415	            String line2 = ownerDto.getAddressLine2();
416	            if (line2 != null && !line2.trim().isEmpty()) {
417	                composed = composed + " " + AddressNormalizer.normalize(line2);
418	            }
419	            return composed;
420	        }
421	        return AddressNormalizer.normalize(ownerDto.getAddress());
422	    }
423	
424	    /**
425	     * Normalize a telephone number for storage into E.164 form (see {@link E164Telephone}).
426	     * The requirement that a valid E.164 number can be formed is enforced separately by
427	     * {@code TelephoneValidation}, so for already-validated input this returns the E.164
428	     * string; it is idempotent, so re-normalizing a stored value yields the same value.
429	     * {@code @Named} keeps this out of MapStruct's automatic method selection, so it only
430	     * runs where a mapping explicitly references it via {@code qualifiedByName}.
431	     */
432	    @Named("normalizeTelephone")
433	    default String normalizeTelephone(String telephone) {
434	        return E164Telephone.normalize(telephone);
435	    }
436	
437	    /**
438	     * Normalize an email address for storage by lower-casing it, so it is persisted and
439	     * returned in a canonical form regardless of the casing supplied by the caller.
440	     * Syntactic validity is enforced separately by the {@code @Email} constraint on the DTO.
441	     * {@code @Named} keeps this out of MapStruct's automatic method selection, so it only
442	     * runs where a mapping explicitly references it via {@code qualifiedByName}.
443	     */
444	    @Named("normalizeEmail")
445	    default String normalizeEmail(String email) {
446	        return email == null ? null : email.toLowerCase();
447	    }
448	
449	    List<OwnerDto> toOwnerDtoCollection(Collection<Owner> ownerCollection);
450	
451	    Collection<Owner> toOwners(Collection<OwnerDto> ownerDtos);
452	
453	    default OwnerPageDto toOwnerPageDto(@NonNull Page<Owner> ownerPage) {
454	        OwnerPageDto ownerPageDto = new OwnerPageDto();
455	        ownerPageDto.setContent(toOwnerDtoCollection(ownerPage.getContent()));
456	        ownerPageDto.setPage(ownerPage.getNumber());
457	        ownerPageDto.setSize(ownerPage.getSize());
458	        ownerPageDto.setTotalElements(ownerPage.getTotalElements());
459	        ownerPageDto.setTotalPages(ownerPage.getTotalPages());
460	        return ownerPageDto;
461	    }
462	}
